#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# KIT-366: Scenario flows move out of kit-collective into the Holdout repo, and the
# AFK developer's GH_TOKEN stops reaching the Holdout. Every step here is a
# person's: an agent types no credential and runs no gh or git against the Holdout.
#
#   Stages 1 and 2 run on the Mac:        bash scripts/holdout-flows-wizard.sh
#   Stages 3 to 5 run on bb-harness, in a terminal of a bb thread there, from a
#   checkout that has this file (the KIT-366 branch until it lands):
#                                          bash scripts/holdout-flows-wizard.sh --from 3
#
# Docs: docs/agents/scenarios.md ("The Holdout token") and docs/agents/device-flows.md.

TOTAL_STAGES=5

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"

FROM=1
if [[ "${1:-}" == "--from" && "${2:-}" =~ ^[1-5]$ ]]; then
  FROM="$2"
elif [[ $# -gt 0 ]]; then
  printf 'Usage: bash scripts/holdout-flows-wizard.sh [--from <1-5>]\n' >&2
  exit 2
fi

# The repos come from factory.config.json; neither name is typed below.
HOLDOUT="$(node -e 'process.stdout.write(require("./factory.config.json").scenarios.holdoutRepo)')"
OWNER_REPO="$(node -e 'process.stdout.write(require("./factory.config.json").github.ownerRepo)')"
ORG="${OWNER_REPO%%/*}"
# The template's set_secret writes to the repo gh infers; name it.
export GH_REPO="$OWNER_REPO"

# bb-harness's main checkout, whose gitignored .env holds the machine's secrets (docs/agents/bb-harness.md).
HARNESS_MAIN="/home/node/work/kit-collective"
on_harness() { [[ -d "$HARNESS_MAIN" ]] && command -v bb >/dev/null 2>&1; }

new_token_page="https://github.com/settings/personal-access-tokens/new"

stage_1() {
  stage "Mac — put the producer workflow into the Holdout repo"
  say "The flow artifact is made in the Holdout repo ($HOLDOUT), by its own"
  say ".github/workflows/scenario-flow.yml. The source is docs/agents/holdout-scenario-flow.yml."
  say "Uses your own gh and git login (it needs the 'workflow' scope to push a workflow file)."
  local branch dir
  branch="$(gh api "repos/$HOLDOUT" --jq .default_branch)" || { warn "gh cannot read $HOLDOUT with your login"; exit 1; }
  say "The Holdout's default branch is: $branch"
  if [[ "$branch" != main ]]; then
    warn "The scenarios CLI dispatches the producer on 'main' (HOLDOUT_REF in scripts/lib/scenarios.mjs)."
    warn "Stop here and tell the KIT-366 session the default branch is '$branch'."
    exit 1
  fi
  dir="$(mktemp -d)"
  git clone -q --depth 1 "https://github.com/$HOLDOUT.git" "$dir"
  mkdir -p "$dir/.github/workflows"
  cp docs/agents/holdout-scenario-flow.yml "$dir/.github/workflows/scenario-flow.yml"
  git -C "$dir" add .github/workflows/scenario-flow.yml
  if git -C "$dir" diff --cached --quiet; then
    say "The Holdout's main already has this producer. Nothing to push."
  else
    confirm "Push .github/workflows/scenario-flow.yml to $HOLDOUT main?" || { warn "skipped"; rm -rf "$dir"; exit 1; }
    git -C "$dir" commit -qm "Scenario flow producer (KIT-366)"
    if ! git -C "$dir" push -q origin HEAD:main; then
      warn "The push was refused. If git names the 'workflow' scope: gh auth refresh -s workflow, then run this stage again."
      rm -rf "$dir"
      exit 1
    fi
    say "Pushed."
  fi
  rm -rf "$dir"
  gh api "repos/$HOLDOUT/actions/workflows/scenario-flow.yml" --jq '"Workflow state: " + .state'
  pause "The state should be 'active'. Press Enter."
}

stage_2() {
  stage "Mac — SCENARIO_FLOWS_TOKEN, the secret the hosted run downloads the flow with"
  say "A fine-grained token that can only read the Holdout repo's Actions artifacts."
  open_url "$new_token_page"
  step "Token name: kit-collective device-flows reads Holdout flows. Expiration: a date (90 days)."
  step "Resource owner: $ORG."
  step "Repository access: Only select repositories → $HOLDOUT, nothing else."
  step "Repository permissions: Actions → Read-only. Leave every other permission at No access"
  step "(Metadata: Read-only is added by GitHub on its own)."
  step "Generate token, then copy it."
  note "If $ORG requires approval for fine-grained tokens, the token reads nothing until it is"
  note "approved: $ORG → Settings → Personal access tokens → Pending requests → approve it."
  ask_secret SCENARIO_FLOWS_TOKEN "Paste the token (hidden):"
  [[ -n "$SCENARIO_FLOWS_TOKEN" ]] || { warn "no token given"; exit 1; }
  set_secret SCENARIO_FLOWS_TOKEN "$SCENARIO_FLOWS_TOKEN"
  unset SCENARIO_FLOWS_TOKEN
  if gh secret list --repo "$OWNER_REPO" | grep -qE '^SCENARIO_FLOWS_TOKEN[[:space:]]'; then
    say "The Actions secret SCENARIO_FLOWS_TOKEN is on $OWNER_REPO."
  else
    warn "SCENARIO_FLOWS_TOKEN is not listed on $OWNER_REPO; set it by hand: gh secret set SCENARIO_FLOWS_TOKEN --repo $OWNER_REPO"
  fi
  pause "Press Enter."
}

# Stages 3 to 5 change bb-harness. Off it, say where to go on and stop.
harness_or_stop() {
  if on_harness; then
    return 0
  fi
  say "Stages $1 to 5 run on bb-harness: open a terminal in a bb thread there, in a checkout that"
  say "has this file (a worktree of the KIT-366 branch until it lands), and run:"
  say "  bash scripts/holdout-flows-wizard.sh --from $1"
  finish
  exit 0
}

# Writes one secret into the main checkout's .env through bb's secure form (the value never
# passes through this script).
request_secret() {
  local name="$1"
  say "Running: bb secret request $name --write-env $HARNESS_MAIN/.env"
  say "It opens bb's secure form; type the token there."
  confirm "Open the form for $name now?" || { warn "skipped"; exit 1; }
  bb secret request "$name" --write-env "$HARNESS_MAIN/.env"
}

stage_3() {
  harness_or_stop 3
  stage "bb-harness — SCENARIOS_GH_TOKEN, the scenarios CLI's own Holdout token"
  say "Every Holdout call of node scripts/scenarios.mjs (titles, read, put, check, report, flow)"
  say "runs with this token, so stage 4 can take the Holdout away from GH_TOKEN."
  say "Done before stage 4, so the AFK developer's titles --issue keeps its answer."
  say "Create it in a browser (on the Mac is fine):"
  step "$new_token_page"
  step "Token name: bb-harness scenarios CLI. Expiration: a date (90 days). Resource owner: $ORG."
  step "Repository access: Only select repositories → $HOLDOUT, nothing else."
  step "Repository permissions: Contents → Read and write; Actions → Read and write."
  step "Every other permission: No access. Generate it and copy it."
  note "Pending approval in $ORG, as in stage 2, makes it read nothing until approved."
  pause "Token copied? Press Enter."
  request_secret SCENARIOS_GH_TOKEN
  say "Checking the token (the gh login still reads the Holdout here, so expect"
  say "'ambient reads, cli reads' and exit 1; 'cli reads' is what this stage proves):"
  node scripts/scenarios.mjs access || true
  pause "Does the line say 'cli reads'? If it says 'cli denied', approve the token in $ORG first. Press Enter."
}

# Decides from the hook's status lines whether gh now holds the .env token. Returns 1 with the fix.
stage4_hook_verdict() {
  case "$1" in
    *"gh re-logged in from .env"*) ;;
    *"gh logged in from .env"*) ;;
    *"gh auth OK (kept the stored login)"*)
      warn "The hook kept the old gh login, so the new GH_TOKEN never reached gh."
      warn "Set GH_LOGIN_FROM_ENV=1 in $HARNESS_MAIN/.env (a setting, not a secret; bb-harness only),"
      warn "then run --from 4 again. Nothing is revoked yet."
      return 1 ;;
    *"gh auth OK"*) say "  gh already holds the .env token (a rerun after a successful rotation)." ;;
    *)
      warn "The hook did not say gh was logged in from .env. Do not revoke the old token."
      warn "Set GH_LOGIN_FROM_ENV=1 in $HARNESS_MAIN/.env, then run --from 4 again."
      return 1 ;;
  esac
}

stage_4() {
  harness_or_stop 4
  stage "bb-harness — a GH_TOKEN that selects kit-collective only"
  warn "Until KIT-366 is on development, development's scenarios CLI does not know"
  warn "SCENARIOS_GH_TOKEN: after this stage the AFK developer gets 'no Scenarios (the scenarios"
  warn "CLI gave no usable answer)' and Milestone scenarios cannot read the Holdout. If a milestone"
  warn "is about to be judged, stop here and run --from 4 after KIT-366 lands."
  confirm "Go on with stage 4 now?" || { warn "stopped before stage 4"; finish; exit 0; }
  say "The bb-harness GH_TOKEN today is a classic token with the repo scope, which reads every"
  say "repo of $ORG, the Holdout included. Replace it with a fine-grained one:"
  step "$new_token_page"
  step "Token name: bb-harness GH_TOKEN (kit-collective only). Expiration: a date. Resource owner: $ORG."
  step "Repository access: Only select repositories → $OWNER_REPO, nothing else."
  step "Repository permissions, Read and write: Actions (dispatches, runs, artifacts),"
  step "  Commit statuses (Device flows, Scenarios, kc/audit), Contents (push, merge),"
  step "  Issues (labels), Pull requests (create, label, merge, auto-merge), Workflows"
  step "  (pushing branches that change .github/workflows)."
  step "Repository permissions, Read-only: Checks (gh pr checks, check-runs). Metadata is added."
  step "Every other permission: No access. Generate it and copy it."
  pause "Token copied? Press Enter."
  request_secret GH_TOKEN
  say "gh does not need to be logged out first. .bb-env-setup.sh logs gh in again from the new GH_TOKEN in the"
  say ".env whenever the token gh stores differs (it needs GH_LOGIN_FROM_ENV=1 in that .env;"
  say "a GH_TOKEN in this shell's env never replaces the stored login, so it runs without one)."
  say "Expect 'gh re-logged in from .env'. A rerun after a successful rotation shows 'gh auth OK'."
  say "'gh auth OK (kept the stored login)' means GH_LOGIN_FROM_ENV=1 is missing: the wizard stops there."
  confirm "Run the hook so gh logs in again from the new GH_TOKEN?" || { warn "skipped"; exit 1; }
  local hook_out
  hook_out="$(cd "$HARNESS_MAIN" && env -u GH_TOKEN -u GITHUB_TOKEN bash .bb-env-setup.sh)" || { printf '%s\n' "$hook_out"; warn "The hook failed: fix what it names, then run --from 4 again."; exit 1; }
  printf '%s\n' "$hook_out"
  # The hook is the one reader of .env: its status lines (no secret) decide, not a second parser here.
  stage4_hook_verdict "$hook_out" || exit 1
  env -u GH_TOKEN -u GITHUB_TOKEN gh auth status -h github.com || { warn "gh is not logged in"; exit 1; }
  say "Checking that the stored token reads $OWNER_REPO before the old one goes:"
  local seen
  seen="$(env -u GH_TOKEN -u GITHUB_TOKEN gh api "repos/$OWNER_REPO" --jq .full_name)" || seen=""
  if [[ "$seen" != "$OWNER_REPO" ]]; then
    warn "The new GH_TOKEN cannot read $OWNER_REPO (approval pending in $ORG, or the repo is not selected)."
    warn "Do not revoke the old token. Fix the new one, then run --from 4 again."
    exit 1
  fi
  say "  ✓ $seen"
  say "Now revoke the old classic token, so it reads nothing anywhere:"
  open_url "https://github.com/settings/tokens"
  step "Find the classic token bb-harness used (scope repo) and Delete it."
  note "If a bb thread exports GH_TOKEN into its env, start new threads: old ones keep the old value."
  pause "Revoked? Press Enter."
}

stage_5() {
  harness_or_stop 5
  stage "bb-harness — prove the split"
  note "Every check runs without GH_TOKEN in its env, so it sees the gh login a new thread gets,"
  note "not a stale token this shell may still hold."
  say "1. The gh login gets 404 on the Holdout repo and its artifacts; the CLI's token reads both."
  say "   Expect exit 0 and 'SCENARIOS access: ambient denied, cli reads':"
  if env -u GH_TOKEN -u GITHUB_TOKEN node scripts/scenarios.mjs access; then
    say "   ✓ Paste that line to the KIT-366 session (it goes under Evidence on the issue)."
  else
    warn "   Not the split yet. 'ambient reads': gh still has the old token (stage 4's re-login did not happen) or it"
    warn "   is not revoked. 'cli unset' or 'cli denied': stage 3. 'UNKNOWN: ... 401/403': a revoked"
    warn "   token, a missing permission or a rate limit on the side it names; nothing is proven."
  fi
  say "2. The fixture titles through the CLI (expect exit 0, 2 Scenarios):"
  env -u GH_TOKEN -u GITHUB_TOKEN node scripts/scenarios.mjs titles --project "Holdout Scenarios" --milestone Fixture || warn "exit $?: see docs/agents/scenarios.md"
  say "3. kit-collective with the new GH_TOKEN (expect a PR number or nothing, and the workflow count):"
  env -u GH_TOKEN -u GITHUB_TOKEN gh pr list --repo "$OWNER_REPO" --limit 1 --json number --jq '.[].number' || warn "gh pr list failed: a missing permission in stage 4"
  env -u GH_TOKEN -u GITHUB_TOKEN gh api "repos/$OWNER_REPO/actions/workflows" --jq '"workflows: " + (.total_count | tostring)' || warn "Actions read failed: stage 4"
  note "The next AFK developer run is the full check of the stage 4 permissions; watch it."
  pause "Press Enter to finish."
}

banner "Scenario flows in the Holdout repo (KIT-366)"
for n in 1 2 3 4 5; do
  if (( n < FROM )); then
    _STAGE_INDEX=$((_STAGE_INDEX + 1))
    continue
  fi
  "stage_$n"
done

finish
